/* Native Figma importer. Generated data is prepended by build.cjs. */
const REPORT = { pages: [], screens: [], sections: [], edges: [], warnings: [], createdNodeIds: [] };
let tokens = {}, styles = [], buttons = {}, fieldMasters = {}, bannerMasters = {}, activeEdges = [], activeMap = {}, styleJobs = [];
const palette = {ink:'#101A2E',paper:'#F5F7FA',panel:'#FFFFFF',line:'#E2E6ED',blue:'#2D5FD2','blue-dark':'#1C42D3','blue-tint':'#E8EEFC',rust:'#A14E3D','rust-tint':'#F5E4E0',muted:'#5F6B7D',success:'#20664A','success-tint':'#E8F5EE'};
const rgb = hex => ({r:parseInt(hex.slice(1,3),16)/255,g:parseInt(hex.slice(3,5),16)/255,b:parseInt(hex.slice(5,7),16)/255});
function paint(name){const p={type:'SOLID',color:rgb(palette[name]||name)};return tokens[name]?figma.variables.setBoundVariableForPaint(p,'color',tokens[name]):p;}
function track(n){REPORT.createdNodeIds.push(n.id);return n;}
function stack(name,w,dir='VERTICAL',gap=16,pad=0,bg=null){const n=track(figma.createFrame());n.name=name;n.layoutMode=dir;n.resize(w,100);n.primaryAxisSizingMode=dir==='VERTICAL'?'AUTO':'FIXED';n.counterAxisSizingMode=dir==='VERTICAL'?'FIXED':'AUTO';n.itemSpacing=gap;n.paddingTop=n.paddingBottom=n.paddingLeft=n.paddingRight=pad;n.fills=bg?[paint(bg)]:[];n.clipsContent=false;for(const k of ['paddingTop','paddingBottom','paddingLeft','paddingRight'])if(tokens['spacing/'+pad])n.setBoundVariable(k,tokens['spacing/'+pad]);if(tokens['spacing/'+gap])n.setBoundVariable('itemSpacing',tokens['spacing/'+gap]);return n;}
function txt(str,w,size=14,bold=false,color='ink'){const n=track(figma.createText());n.name=str.slice(0,70);n.fontName={family:size>=20?'Plus Jakarta Sans':'Inter',style:size>=20?'Bold':bold?'Semi Bold':'Regular'};n.fontSize=size;n.lineHeight={unit:'PERCENT',value:145};n.characters=String(str);n.textAutoResize='HEIGHT';n.resize(w,24);n.fills=[paint(color)];const style=styles.find(s=>s.fontSize===size&&s.fontName.family===n.fontName.family&&s.fontName.style===n.fontName.style);if(style)styleJobs.push({n,id:style.id});return n;}
async function flushStyles(){const jobs=styleJobs;styleJobs=[];await Promise.all(jobs.map(async job=>{await job.n.setTextStyleIdAsync(job.id);job.n.lineHeight={unit:'PERCENT',value:145};}));}
function add(parent,n){parent.appendChild(n);return n;}
function edge(node,to,mode='desktop',type='screen'){activeEdges.push({node,to,mode,type});return node;}
function rule(parent,w){const l=track(figma.createRectangle());l.name='Divider';l.resize(w,1);l.fills=[paint('line')];add(parent,l);return l;}
function button(label,to,w=220,style='primary',mode='desktop'){const master=buttons[style==='primary'?'primary':'outline'];let n;if(master){n=track(master.createInstance());const p=Object.keys(master.componentPropertyDefinitions).find(k=>k.startsWith('Label'));n.setProperties({[p]:label});n.resize(w,44);n.primaryAxisSizingMode='FIXED';n.counterAxisSizingMode='FIXED';n.primaryAxisAlignItems='CENTER';n.counterAxisAlignItems='CENTER';const t=n.findOne(x=>x.type==='TEXT');if(t){t.textAutoResize='HEIGHT';t.resize(Math.max(w-24,40),22);t.textAlignHorizontal='CENTER';}}else{n=stack('Button',w,'HORIZONTAL',0,12,style==='primary'?'blue':'panel');n.strokes=style==='primary'?[]:[paint('line')];add(n,txt(label,w-24,14,true,style==='primary'?'panel':'ink'));}n.name='Action / '+label;if(to)edge(n,to,mode);return n;}
function actionRows(parent,actions,w,mobile,mode){let row=null,used=0;for(const a of actions||[]){const bw=mobile?w:Math.min(310,Math.max(142,a.label.length*7.3+32));if(!row||used+bw>w){row=stack('Actions',w,'HORIZONTAL',12);add(parent,row);used=0;}add(row,button(a.label,a.to,bw,a.style,mode));used+=bw+12;if(mobile)row=null;}}
function pill(text,w=110,tone='blue'){const n=stack('Status / '+text,w,'HORIZONTAL',0,6,tone==='success'?'success-tint':tone==='rust'?'rust-tint':'blue-tint');add(n,txt(text,w-12,12,true,tone));return n;}
function field(parent,f,w){const master=fieldMasters[f.error?'Error':'Default'];const inst=track(master.createInstance());const props={};for(const [key,value]of Object.entries({Label:f.label,Value:f.value||'Enter '+f.label.toLowerCase(),Help:f.help||' '})){props[Object.keys(master.componentPropertyDefinitions).find(k=>k.startsWith(key+'#'))]=value;}inst.setProperties(props);add(parent,inst);inst.resize(w,inst.height);inst.primaryAxisSizingMode='AUTO';for(const n of inst.findAll(x=>x.type==='TEXT')){const target=n.parent===inst?w:w-26;n.textAutoResize='HEIGHT';n.resize(target,Math.max(18,n.height));}return inst;}
function banner(parent,state,title,body,w){const m=bannerMasters[state==='error'?'Error':state==='success'?'Success':state==='warning'?'Warning':'Info'];const inst=track(m.createInstance());const props={};for(const [key,value]of Object.entries({Title:title,Body:body||' '}))props[Object.keys(m.componentPropertyDefinitions).find(k=>k.startsWith(key+'#'))]=value;inst.setProperties(props);add(parent,inst);inst.resize(w,inst.height);inst.primaryAxisSizingMode='AUTO';for(const n of inst.findAll(x=>x.type==='TEXT')){n.textAutoResize='HEIGHT';n.resize(w-32,n.height);}return inst;}
function card(parent,name,w){const n=stack(name,w,'VERTICAL',16,24,'panel');n.strokes=[paint('line')];n.strokeWeight=1;n.cornerRadius=3;add(parent,n);return n;}
function facts(parent,values,w){for(const [label,value]of values||[]){const row=stack(label,w,'VERTICAL',5);add(row,txt(label.toUpperCase(),w,11,true,'muted'));add(row,txt(value,w,15,true));add(parent,row);}}
function table(parent,rows,columns,w,mobile,to,mode){const n=stack('Records',w,'VERTICAL',0,0,'panel');n.strokes=[paint('line')];add(parent,n);if(!mobile&&columns){const head=stack('Column headings',w,'HORIZONTAL',16,16,'paper');for(const c of columns)add(head,txt(c,(w-32-48)/4,12,true,'muted'));add(n,head);}for(let ri=0;ri<(rows||[]).length;ri++){const values=rows[ri];const r=stack('Record / '+values[0],w,mobile?'VERTICAL':'HORIZONTAL',mobile?8:16,16);for(let i=0;i<values.length;i++){const col=String(values[i]).match(/Paid|Available|Active|Published|Delivered|Verified/)?'success':String(values[i]).match(/Pending|Reserved|Draft|Expired|Unavailable/)?'rust':i===0?'ink':'muted';add(r,txt(values[i],mobile?w-32:(w-32-16*(values.length-1))/values.length,13,i===0,col));}if(to){let target=to;if(values.some(v=>/Reserved/.test(v))&&to==='sale-detail')target='sale-blocked';if(values.some(v=>/Reserved/.test(v))&&to==='inventory-detail')target='inventory-blocked';if(values.some(v=>/Payment pending/.test(v))&&to==='orders-detail')target='orders-payment';edge(r,target,mode);}add(n,r);if(ri<rows.length-1)rule(n,w);}return n;}
function totals(parent,items,w){const n=card(parent,'Order summary',w);add(n,txt('Order summary',w-48,20,true));for(let i=0;i<items.length;i++){const [l,v]=items[i];if(i===items.length-1)rule(n,w-48);const r=stack(l,w-48,'HORIZONTAL',12);add(r,txt(l,(w-60)*.52,14,i===items.length-1));add(r,txt(v,(w-60)*.48,14,true));add(n,r);}return n;}
function device(parent,w,h=220,kind='phone'){const box=stack('Device illustration',w,'HORIZONTAL',0,24,'blue-tint');box.resize(w,h);box.primaryAxisSizingMode='FIXED';box.counterAxisSizingMode='FIXED';box.primaryAxisAlignItems='CENTER';box.counterAxisAlignItems='CENTER';const d=track(figma.createFrame());d.name=kind==='laptop'?'Laptop silhouette':'Phone silhouette';d.resize(kind==='laptop'?Math.min(w-64,260):92,kind==='laptop'?130:170);d.fills=[paint('ink')];d.cornerRadius=kind==='laptop'?6:16;const screen=track(figma.createRectangle());screen.name='Display';screen.resize(d.width-12,d.height-12);screen.x=6;screen.y=6;screen.fills=[paint('blue')];screen.cornerRadius=kind==='laptop'?3:12;d.appendChild(screen);const camera=track(figma.createEllipse());camera.resize(9,9);camera.x=d.width/2-4.5;camera.y=12;camera.fills=[paint('ink')];d.appendChild(camera);add(box,d);add(parent,box);return box;}
function loading(parent,w){const n=stack('Loading skeleton',w,'VERTICAL',12);for(const width of [w,w*.8,w*.6]){const r=track(figma.createRectangle());r.name='Loading placeholder';r.resize(width,18);r.fills=[paint('line')];add(n,r);}add(parent,n);}
function storeHeader(root,w,mobile,mode){const bar=stack('Store navigation',w,'HORIZONTAL',16, mobile?20:32,'ink');bar.counterAxisAlignItems='CENTER';const brand=txt('▤  Softwallet',mobile?186:240,20,true,'panel');add(bar,brand);edge(brand,'home',mode);if(mobile){const menu=txt('Menu',64,14,true,'panel');add(bar,menu);edge(menu,'mobile-menu',mode);const cart=txt('Cart',40,14,true,'panel');add(bar,cart);edge(cart,'cart',mode);}else{const links=[['Shop','catalog'],['UK-used','used'],['Search','search'],['My account','account'],['Cart (3)','cart']];for(const [label,to]of links){const n=txt(label,label==='My account'?136:110,14,true,'panel');add(bar,n);edge(n,to,mode);}}add(root,bar);}
function adminShell(root,w,mobile,mode,active){if(mobile){const head=stack('Admin navigation',w,'HORIZONTAL',16,20,'ink');add(head,txt('▤  Softwallet',250,20,true,'panel'));const b=txt('Menu',64,14,true,'panel');add(head,b);edge(b,'admin-menu',mode);add(root,head);return root;}const shell=stack('Admin shell',w,'HORIZONTAL',0);add(root,shell);const nav=stack('Sidebar',224,'VERTICAL',6,20,'ink');nav.resize(224,980);nav.primaryAxisSizingMode='FIXED';add(nav,txt('▤  Softwallet',184,20,true,'panel'));add(nav,txt('STORE WORKSPACE',184,10,true,'panel'));for(const m of DATA.modules){const link=stack('Nav / '+m.name,184,'HORIZONTAL',0,10,m.key===active?'blue':null);const t=txt(m.name,164,13,m.key===active,'panel');add(link,t);edge(link,m.key,mode);add(nav,link);}add(nav,txt('Super admin · Demo',184,11,false,'panel'));add(shell,nav);const main=stack('Main workspace',w-224,'VERTICAL',0);add(shell,main);return main;}
function productGrid(parent,s,w,mobile,mode){const names=s.products||['iPhone 12','Samsung Galaxy S24','Apple 20W charger'];const prices=s.products?['₦750,000','₦420,000','₦380,000']:['₦620,000','₦1,150,000','₦17,000'];const row=stack('Product grid',w,mobile?'VERTICAL':'HORIZONTAL',20);add(parent,row);for(let i=0;i<3;i++){const cw=mobile?w:(w-40)/3;const c=card(row,names[i],cw);device(c,cw-48,200,s.products?'laptop':'phone');add(c,txt(i===2&&!s.products?'NEW · ACCESSORY':'IN STOCK',cw-48,10,true,'blue'));add(c,txt(names[i],cw-48,18,true));add(c,txt(s.products?'Inspected · UK-used':'New · Available now',cw-48,13,false,'muted'));add(c,txt(prices[i],cw-48,20,true));add(c,button('View product',s.products?'laptop-product':s.id==='used'?'used-product':'product',cw-48,'outline',mode));}}
